import React from 'react';
import jsPDF from 'jspdf';

function DownloadPDF({ resumeData }) {
  const handleDownload = () => {
    const doc = new jsPDF();
    let y = 10;
    doc.setFontSize(18);
    doc.text(resumeData.name || '', 10, y);
    y += 10;
    doc.setFontSize(12);
    doc.text(`Email: ${resumeData.email || ''}`, 10, y);
    y += 7;
    doc.text(`Phone: ${resumeData.phone || ''}`, 10, y);
    y += 10;
    doc.setFontSize(14);
    doc.text('Professional Summary', 10, y);
    y += 7;
    doc.setFontSize(12);
    doc.text(resumeData.summary || '', 10, y);
    y += 15;
    doc.setFontSize(14);
    doc.text('Experience', 10, y);
    y += 7;
    doc.setFontSize(12);
    doc.text(resumeData.experience || '', 10, y);
    y += 15;
    doc.setFontSize(14);
    doc.text('Education', 10, y);
    y += 7;
    doc.setFontSize(12);
    doc.text(resumeData.education || '', 10, y);
    y += 15;
    doc.setFontSize(14);
    doc.text('Skills', 10, y);
    y += 7;
    doc.setFontSize(12);
    if (resumeData.skills) {
      resumeData.skills.split(',').forEach((skill, i) => {
        doc.text(`- ${skill.trim()}`, 12, y + i * 7);
      });
    }
    doc.save('resume.pdf');
  };

  return (
    <button onClick={handleDownload} style={{marginTop: '16px', padding: '10px 20px', background: '#28a745', color: '#fff', border: 'none', borderRadius: '4px', cursor: 'pointer'}}>
      Download as PDF
    </button>
  );
}

export default DownloadPDF;
